//! Purpose:
//! Builds callable descriptor support reused by eval-to-native constructor and
//! method bridges.
//!
//! Called from:
//! - `crate::codegen::finalize_user_asm()`.
//! - `crate::codegen::eval_constructor_helpers` and
//!   `crate::codegen::eval_method_helpers`.
//!
//! Key details:
//! - Eval stores PHP callbacks as boxed runtime values, while AOT callable
//!   parameters expect descriptor pointers.
//! - String callables and static callable arrays select static descriptors with
//!   uniform invokers generated by the existing callable dispatch machinery.
//! - Inline invoker emission is filed out of line, so the enclosing helper stays contiguous in its section.
//! - AOT callback descriptors emitted here bind raw public argument containers.

use crate::codegen::abi;
use crate::codegen::callable_descriptor::{
    self, CallableDescriptorInvocation, CallableDescriptorShape,
};
use crate::fast_hash::{FastMap as HashMap, FastSet as HashSet};

use crate::codegen::callable_dispatch::{
    self, RuntimeCallableCase, RuntimeCallableSelector, RuntimeStaticMethodCallableCase,
};
use crate::codegen::data_section::DataSection;
use crate::codegen::emit::Emitter;
use crate::codegen::runtime_callable_invoker::RuntimeCallableInvoker;
use crate::ir::Module;
use crate::codegen::lower_inst::builtins::eval::{
    eval_native_function_bridge_supported, eval_native_instance_method_bridge_supported,
    eval_native_static_method_bridge_supported,
};
use crate::names::{function_symbol, method_symbol, php_symbol_key, static_method_symbol};
use crate::parser::ast::Visibility;
use crate::types::{callable_wrapper_sig, FunctionSig, PhpType};

#[cfg(test)]
mod tests;

const EVAL_RECEIVER_CAPTURE_PARAM: &str = "__elephc_eval_callable_receiver";
/// Frame slot the eval ARGUMENT bridges stage a boxed value in before a cast reads it.
///
/// Another bridge with another frame passes its own offset instead; the casts themselves no longer
/// assume one.
pub(super) const EVAL_ARG_BOXED_VALUE_AARCH64_OFFSET: i64 = -16;
/// The x86_64 twin of [`EVAL_ARG_BOXED_VALUE_AARCH64_OFFSET`], as a `[rbp - N]` displacement.
pub(super) const EVAL_ARG_BOXED_VALUE_X86_64_OFFSET: usize = 40;
/// Frame slot the eval ARGUMENT bridges hold the active eval context in, as `[x29 + N]`.
pub(super) const EVAL_ARG_CONTEXT_AARCH64_OFFSET: i64 = AARCH64_EVAL_CONTEXT_FROM_FP_OFFSET;
const MIXED_METHOD_TAG_OFFSET: usize = 0;
const MIXED_METHOD_PAYLOAD_OFFSET: usize = 16;
const MIXED_RECEIVER_TAG_OFFSET: usize = 32;
const MIXED_RECEIVER_PAYLOAD_OFFSET: usize = 48;
const MIXED_SELECTOR_BYTES: usize = 64;
const SAVED_OBJECT_RECEIVER_BYTES: usize = 16;
const MIXED_TAG_STRING: i64 = 1;
const MIXED_TAG_OBJECT: i64 = 6;
pub(crate) const EVAL_DYNAMIC_CALLABLE_INVOKER_LABEL: &str = "__elephc_eval_dynamic_callable_invoker";
pub(crate) const EVAL_DYNAMIC_CALLABLE_ENTRY_LABEL: &str = "__elephc_eval_dynamic_callable_entry";
/// Global wrapper that turns `(context, boxed callback)` into an owned adapter descriptor.
pub(crate) const EVAL_CALLBACK_WRAPPER_LABEL: &str = "__elephc_eval_wrap_callback";
const EVAL_DYNAMIC_CONTEXT_CAPTURE: usize = 0;
const EVAL_DYNAMIC_CALLBACK_CAPTURE: usize = 1;
const EVAL_DYNAMIC_CALLABLE_CAPTURE_BYTES: usize = 32;
const AARCH64_EVAL_CONTEXT_FROM_FP_OFFSET: i64 = 16;
const EVAL_CALLABLE_LOOKUP_FRAME_SIZE: usize = 32;
const EVAL_CALLABLE_LOOKUP_SELECTOR_OFFSET: usize = 16;
const EVAL_CALLABLE_STRING_SELECTOR_BYTES: usize = 16;
const EVAL_CALLABLE_ARRAY_SELECTOR_BYTES: usize = MIXED_SELECTOR_BYTES;
const EVAL_CALLABLE_OBJECT_SELECTOR_BYTES: usize = SAVED_OBJECT_RECEIVER_BYTES;
// Nested pushes grow below the reserved area and are balanced before the
// epilogue, so the reserved sizes only need to cover the copied selectors.
const EVAL_CALLABLE_STRING_SCRATCH_BYTES: usize = 16;
const EVAL_CALLABLE_ARRAY_SCRATCH_BYTES: usize = 64;
const EVAL_CALLABLE_OBJECT_SCRATCH_BYTES: usize = 16;

/// Callable descriptors available to eval constructor and method bridges.
pub(super) struct EvalCallableDescriptorSupport {
    pub(super) argument_normalizer_needed: bool,
    string_cases: Vec<RuntimeCallableCase>,
    instance_array_cases: Vec<EvalInstanceMethodCallableCase>,
    static_array_cases: Vec<RuntimeStaticMethodCallableCase>,
    object_cases: Vec<EvalInstanceMethodCallableCase>,
    dynamic_descriptor_label: Option<String>,
    string_lookup_label: Option<String>,
    array_lookup_label: Option<String>,
    object_lookup_label: Option<String>,
}

/// Runtime instance-method callable case emitted specifically for eval bridges.
#[derive(Clone)]
struct EvalInstanceMethodCallableCase {
    class_id: u64,
    method_name: String,
    case: RuntimeCallableCase,
}

/// Receiver-bound callable descriptor shape used by eval bridge metadata.
#[derive(Clone, Copy)]
enum EvalInstanceCallableShape {
    InstanceMethod,
    ObjectInvoke,
}

/// Label an eval invoker is emitted under until its text is known to be new.
const PENDING_INVOKER_LABEL: &str = "__elephc_eval_callable_invoker_pending";

/// Stable label allocator for eval bridge helper bodies emitted outside `FunctionContext`.
struct EvalCallableEmitState {
    next_id: usize,
    argument_normalizer_needed: bool,
    /// Emitted invoker bodies, as written under [`PENDING_INVOKER_LABEL`], mapped to the label
    /// that carries that body.
    invoker_bodies: HashMap<String, String>,
    runtime_callable_invokers: Vec<EvalRuntimeCallableInvokerCacheEntry>,
}

/// Cached eval invoker body keyed by its complete ABI-relevant signature and captures.
struct EvalRuntimeCallableInvokerCacheEntry {
    signature: FunctionSig,
    captures: Vec<(String, PhpType, bool)>,
    owns_string_return: bool,
    current_class: Option<String>,
    label: String,
}

impl EvalCallableEmitState {
    /// Creates an empty label state for one eval callable-support emission pass.
    fn new() -> Self {
        Self {
            next_id: 0,
            argument_normalizer_needed: false,
            invoker_bodies: HashMap::default(),
            runtime_callable_invokers: Vec::new(),
        }
    }

    /// Returns the label carrying `body`, an invoker emitted under [`PENDING_INVOKER_LABEL`],
    /// naming and recording it the first time that text is seen.
    ///
    /// The placeholder names the invoker and prefixes each of its local labels, so two bodies
    /// share a label exactly when their instructions are the same. `filed` receives the body
    /// under its real label only when it is new.
    fn emitted_invoker(&mut self, body: String, filed: impl FnOnce(&str)) -> String {
        if let Some(existing) = self.invoker_bodies.get(&body) {
            return existing.clone();
        }
        let label = self.next_label("callable_invoker");
        filed(&body.replace(PENDING_INVOKER_LABEL, &label));
        self.invoker_bodies.insert(body, label.clone());
        label
    }

    /// Returns a unique global/local label for generated eval callable support.
    fn next_label(&mut self, prefix: &str) -> String {
        let id = self.next_id;
        self.next_id += 1;
        format!("__elephc_eval_{}_{}", prefix, id)
    }

    /// Returns the shared invoker body for an identical signature and capture layout.
    fn runtime_callable_invoker(
        &self,
        signature: &FunctionSig,
        captures: &[(String, PhpType, bool)],
        owns_string_return: bool,
        current_class: Option<&str>,
    ) -> Option<String> {
        self.runtime_callable_invokers
            .iter()
            // Cheapest fields first: the signature comparison is the costly one.
            .find(|entry| {
                entry.owns_string_return == owns_string_return
                    && entry.current_class.as_deref() == current_class
                    && entry.captures == captures
                    && entry.signature == *signature
            })
            .map(|entry| entry.label.clone())
    }

    /// Records an emitted invoker body for reuse by later eval descriptors.
    fn cache_runtime_callable_invoker(
        &mut self,
        signature: &FunctionSig,
        captures: &[(String, PhpType, bool)],
        owns_string_return: bool,
        current_class: Option<&str>,
        label: String,
    ) {
        self.runtime_callable_invokers
            .push(EvalRuntimeCallableInvokerCacheEntry {
                signature: signature.clone(),
                captures: captures.to_vec(),
                owns_string_return,
                current_class: current_class.map(str::to_string),
                label,
            });
    }
}

impl EvalCallableDescriptorSupport {
    /// Returns true when eval callback fallback descriptors can be materialized.
    fn has_dynamic_descriptor(&self) -> bool {
        self.dynamic_descriptor_label.is_some()
    }

    /// Returns the static template used for eval-owned runtime descriptors.
    pub(super) fn dynamic_descriptor_label(&self) -> Option<&str> {
        self.dynamic_descriptor_label.as_deref()
    }
}

/// Returns true when eval bridges may need to turn PHP callbacks into descriptors.
pub(super) fn module_needs_eval_callable_descriptor_support(module: &Module) -> bool {
    module_uses_eval(module)
}

/// Returns whether this binary links the eval bridge, and therefore needs these helpers.
///
/// THE INVARIANT IS "LINKED", NOT "USES EVAL". `libelephc_magician.a` references the
/// `__elephc_eval_*` callbacks unconditionally, so any binary that links it must define
/// them or fail to link — `__elephc_eval_reflection_attribute_new` undefined and a dozen
/// like it. This used to scan for functions carrying an eval local instead, which is a
/// different question that happened to give the same answer while the ONLY reason to link
/// the archive was an `eval()` in the program.
///
/// That stopped being the only reason. `opcache_compile_file()` populates the runtime script
/// cache, which lives in the archive, so a program calling it needs the archive whether or
/// not it ever evaluates a string. Keeping the narrower scan here made that combination
/// unlinkable, which is what kept the fold in place and left the function answering `false`
/// where reference answers `true`.
///
/// The call sites are all inside a block already gated on the same flag, so for a program
/// that does use `eval()` nothing changes.
fn module_uses_eval(module: &Module) -> bool {
    module.required_runtime_features.eval_bridge
}


/// Emits shared runtime callable wrappers/invokers and returns descriptor cases.
pub(super) fn emit_eval_callable_descriptor_support(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    needed: bool,
    eval_bridge: bool,
) -> EvalCallableDescriptorSupport {
    if !needed {
        // The per-class CASE TABLES below are what `needed` gates: they are large and only a
        // module that hands AOT callables to the interpreter reads them. The single DYNAMIC
        // descriptor is a different matter — every eval-escape arm of a runtime callable invoker
        // references it, and those arms are emitted on `eval_bridge` alone. Leaving it out when
        // the two conditions disagreed produced an undefined
        // `__elephc_eval_dynamic_callable_entry` at link time for a program that compiles
        // cleanly, so the descriptor follows the condition its REFERENCES follow.
        let dynamic_descriptor_label = eval_bridge.then(|| {
            let label = eval_dynamic_callable_descriptor(data);
            emit_eval_dynamic_callable_invoker(module, emitter, data);
            label
        });
        return EvalCallableDescriptorSupport {
            argument_normalizer_needed: false,
            string_cases: Vec::new(),
            instance_array_cases: Vec::new(),
            static_array_cases: Vec::new(),
            object_cases: Vec::new(),
            dynamic_descriptor_label,
            string_lookup_label: None,
            array_lookup_label: None,
            object_lookup_label: None,
        };
    }
    let mut state = EvalCallableEmitState::new();
    let string_cases = eval_user_function_callable_cases(module, emitter, data, &mut state);
    let instance_array_cases = eval_instance_method_callable_cases(module, emitter, data, &mut state);
    let static_array_cases = eval_static_method_callable_cases(module, emitter, data, &mut state);
    let object_cases = eval_invokable_object_callable_cases(module, emitter, data, &mut state);
    let dynamic_descriptor_label = Some(eval_dynamic_callable_descriptor(data));
    emit_eval_dynamic_callable_invoker(module, emitter, data);
    if let Some(label) = dynamic_descriptor_label.as_deref() {
        emit_eval_callback_wrapper(module, emitter, label);
    }
    let mut support = EvalCallableDescriptorSupport {
        argument_normalizer_needed: state.argument_normalizer_needed,
        string_cases,
        instance_array_cases,
        static_array_cases,
        object_cases,
        dynamic_descriptor_label,
        string_lookup_label: None,
        array_lookup_label: None,
        object_lookup_label: None,
    };
    let string_lookup_label = state.next_label("callable_string_lookup");
    let array_lookup_label = state.next_label("callable_array_lookup");
    let object_lookup_label = state.next_label("callable_object_lookup");
    emit_eval_callable_lookup_helpers(
        emitter,
        data,
        &mut state,
        &support,
        &string_lookup_label,
        &array_lookup_label,
        &object_lookup_label,
    );
    support.string_lookup_label = Some(string_lookup_label);
    support.array_lookup_label = Some(array_lookup_label);
    support.object_lookup_label = Some(object_lookup_label);
    support
}

/// Emits one module-wide static lookup helper for each eval callable category.
///
/// Call sites pass the address of their temporary selector area in the first
/// integer argument register.  Each helper copies that area into a framed
/// local stack region so the existing target-neutral selector comparisons and
/// descriptor capture emitters can be shared without duplicating case tables.
fn emit_eval_callable_lookup_helpers(
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
    support: &EvalCallableDescriptorSupport,
    string_label: &str,
    array_label: &str,
    object_label: &str,
) {
    emit_eval_string_callable_lookup_helper(
        emitter,
        data,
        state,
        &support.string_cases,
        &support.static_array_cases,
        string_label,
    );
    emit_eval_callable_array_lookup_helper(
        emitter,
        data,
        state,
        &support.instance_array_cases,
        &support.static_array_cases,
        array_label,
    );
    emit_eval_invokable_object_lookup_helper(
        emitter,
        state,
        &support.object_cases,
        object_label,
    );
}

/// Emits a framed local selector area for a shared lookup helper.
///
/// The incoming pointer is copied before any selector-based comparison.  The
/// local area grows below the helper frame, so nested pushes can never reach
/// the saved return address or frame pointer.  The caller's stack is never
/// installed as the helper stack pointer.
fn emit_eval_callable_lookup_helper_prologue(
    emitter: &mut Emitter,
    label: &str,
    selector_bytes: usize,
    scratch_bytes: usize,
) {
    emitter.blank();
    emitter.label_global(label);
    abi::emit_frame_prologue(emitter, EVAL_CALLABLE_LOOKUP_FRAME_SIZE);
    let arg_reg = abi::int_arg_reg_name(emitter.target, 0);
    abi::store_at_offset(emitter, arg_reg, EVAL_CALLABLE_LOOKUP_SELECTOR_OFFSET);
    abi::emit_reserve_temporary_stack(emitter, scratch_bytes);
    emit_copy_eval_callable_selector_to_stack(emitter, selector_bytes);
}

/// Copies a caller-owned selector area into the helper's local temporary stack.
fn emit_copy_eval_callable_selector_to_stack(emitter: &mut Emitter, selector_bytes: usize) {
    let stack_reg = abi::secondary_scratch_reg(emitter);
    abi::load_at_offset(
        emitter,
        stack_reg,
        EVAL_CALLABLE_LOOKUP_SELECTOR_OFFSET,
    );
    match emitter.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            for offset in (0..selector_bytes).step_by(8) {
                let value_reg = "x11";
                let source = if offset == 0 {
                    format!("[{}]", stack_reg)
                } else {
                    format!("[{}, #{}]", stack_reg, offset)
                };
                emitter.instruction(&format!("ldr {}, {}", value_reg, source)); // copy one selector word from the caller-owned area
                abi::emit_store_to_sp(emitter, value_reg, offset);
            }
        }
        crate::codegen::platform::Arch::X86_64 => {
            for offset in (0..selector_bytes).step_by(8) {
                let value_reg = "r11";
                let source = if offset == 0 {
                    format!("[{}]", stack_reg)
                } else {
                    format!("[{} + {}]", stack_reg, offset)
                };
                emitter.instruction(&format!("mov {}, QWORD PTR {}", value_reg, source)); // copy one selector word from the caller-owned area
                abi::emit_store_to_sp(emitter, value_reg, offset);
            }
        }
    }
}

/// Emits the miss path and frame restore shared by a lookup helper.
fn emit_eval_callable_lookup_helper_epilogue(
    emitter: &mut Emitter,
    miss_label: &str,
    done_label: &str,
    scratch_bytes: usize,
) {
    emitter.label(miss_label);
    abi::emit_load_int_immediate(emitter, abi::int_result_reg(emitter), 0);
    emitter.label(done_label);
    abi::emit_release_temporary_stack(emitter, scratch_bytes);
    abi::emit_frame_restore(emitter, EVAL_CALLABLE_LOOKUP_FRAME_SIZE);
    abi::emit_return(emitter);
}

/// Emits a module-wide lookup helper for string and static-method callables.
fn emit_eval_string_callable_lookup_helper(
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
    string_cases: &[RuntimeCallableCase],
    static_cases: &[RuntimeStaticMethodCallableCase],
    label: &str,
) {
    emit_eval_callable_lookup_helper_prologue(
        emitter,
        label,
        EVAL_CALLABLE_STRING_SELECTOR_BYTES,
        EVAL_CALLABLE_STRING_SCRATCH_BYTES,
    );
    let done_label = state.next_label("callable_string_lookup_done");
    let miss_label = state.next_label("callable_string_lookup_miss");
    let result_reg = abi::int_result_reg(emitter);
    let selector = RuntimeCallableSelector::StringNameStack {
        ptr_offset: 0,
        len_offset: 8,
        call_reg: result_reg,
    };
    for (index, case) in string_cases
        .iter()
        .chain(static_cases.iter().map(|case| &case.case))
        .enumerate()
    {
        let next_case = state.next_label(&format!("callable_string_lookup_next_{}", index));
        let matched_label = state.next_label(&format!("callable_string_lookup_match_{}", index));
        callable_dispatch::emit_branch_if_callable_case_mismatch(
            &selector,
            case,
            &next_case,
            emitter,
            &matched_label,
            data,
        );
        abi::emit_jump(emitter, &done_label);
        emitter.label(&next_case);
    }
    abi::emit_jump(emitter, &miss_label);
    emit_eval_callable_lookup_helper_epilogue(
        emitter,
        &miss_label,
        &done_label,
        EVAL_CALLABLE_STRING_SCRATCH_BYTES,
    );
}

/// Emits a module-wide lookup helper for instance and static callable arrays.
fn emit_eval_callable_array_lookup_helper(
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
    instance_cases: &[EvalInstanceMethodCallableCase],
    static_cases: &[RuntimeStaticMethodCallableCase],
    label: &str,
) {
    emit_eval_callable_lookup_helper_prologue(
        emitter,
        label,
        EVAL_CALLABLE_ARRAY_SELECTOR_BYTES,
        EVAL_CALLABLE_ARRAY_SCRATCH_BYTES,
    );
    let done_label = state.next_label("callable_array_lookup_done");
    let miss_label = state.next_label("callable_array_lookup_miss");
    let result_reg = abi::int_result_reg(emitter);
    for (index, case) in instance_cases.iter().enumerate() {
        let next_case = state.next_label(&format!("callable_array_lookup_instance_next_{}", index));
        emit_branch_if_instance_callable_array_case_mismatch(emitter, data, case, &next_case);
        emit_runtime_descriptor_with_saved_receiver_capture(
            emitter,
            &case.case.descriptor_label,
            MIXED_RECEIVER_PAYLOAD_OFFSET,
            result_reg,
        );
        abi::emit_jump(emitter, &done_label);
        emitter.label(&next_case);
    }
    for (index, case) in static_cases.iter().enumerate() {
        let next_case = state.next_label(&format!("callable_array_lookup_static_next_{}", index));
        emit_branch_if_static_callable_array_case_mismatch(emitter, data, case, &next_case);
        abi::emit_symbol_address(emitter, result_reg, &case.case.descriptor_label);
        abi::emit_jump(emitter, &done_label);
        emitter.label(&next_case);
    }
    abi::emit_jump(emitter, &miss_label);
    emit_eval_callable_lookup_helper_epilogue(
        emitter,
        &miss_label,
        &done_label,
        EVAL_CALLABLE_ARRAY_SCRATCH_BYTES,
    );
}

/// Emits a module-wide lookup helper for invokable-object callables.
fn emit_eval_invokable_object_lookup_helper(
    emitter: &mut Emitter,
    state: &mut EvalCallableEmitState,
    object_cases: &[EvalInstanceMethodCallableCase],
    label: &str,
) {
    emit_eval_callable_lookup_helper_prologue(
        emitter,
        label,
        EVAL_CALLABLE_OBJECT_SELECTOR_BYTES,
        EVAL_CALLABLE_OBJECT_SCRATCH_BYTES,
    );
    let done_label = state.next_label("callable_object_lookup_done");
    let miss_label = state.next_label("callable_object_lookup_miss");
    let result_reg = abi::int_result_reg(emitter);
    for (index, case) in object_cases.iter().enumerate() {
        let next_case = state.next_label(&format!("callable_object_lookup_next_{}", index));
        emit_branch_if_receiver_class_id_mismatch(emitter, case.class_id, 0, &next_case);
        emit_runtime_descriptor_with_saved_receiver_capture(
            emitter,
            &case.case.descriptor_label,
            0,
            result_reg,
        );
        abi::emit_jump(emitter, &done_label);
        emitter.label(&next_case);
    }
    abi::emit_jump(emitter, &miss_label);
    emit_eval_callable_lookup_helper_epilogue(
        emitter,
        &miss_label,
        &done_label,
        EVAL_CALLABLE_OBJECT_SCRATCH_BYTES,
    );
}

/// Emits the static descriptor template for eval-owned callback values.
pub(crate) fn eval_dynamic_callable_descriptor(data: &mut DataSection) -> String {
    let captures = vec![
        (
            "__elephc_eval_callable_context".to_string(),
            PhpType::Int,
            false,
        ),
        (
            "__elephc_eval_callable_value".to_string(),
            PhpType::Mixed,
            false,
        ),
    ];
    callable_descriptor::static_descriptor_with_optional_invoker_meta(
        data,
        EVAL_DYNAMIC_CALLABLE_ENTRY_LABEL,
        Some("eval callback"),
        callable_descriptor::CALLABLE_DESC_KIND_CALLBACK_ADAPTER,
        None,
        &captures,
        &[],
        CallableDescriptorInvocation::new(CallableDescriptorShape::CallbackAdapter),
        Some(EVAL_DYNAMIC_CALLABLE_INVOKER_LABEL),
    )
}

/// Emits `__elephc_eval_wrap_callback(context, boxed callback) -> owned adapter descriptor`.
///
/// The one place the adapter template label is known, so both the boxed-callable ladder (an
/// eval closure object reaching a native call site) and `__rt_closure_bind` (through the
/// `_elephc_eval_wrap_callback_fn` slot the first eval context fills) turn an eval callback into
/// the descriptor `__elephc_eval_dynamic_callable_invoker` dispatches. The callback capture is
/// retained here; the descriptor's release retires it like any Mixed capture.
fn emit_eval_callback_wrapper(module: &Module, emitter: &mut Emitter, descriptor_label: &str) {
    emitter.blank();
    emitter.comment("--- eval bridge: callback adapter wrapper ---");
    emitter.label_global(EVAL_CALLBACK_WRAPPER_LABEL);
    let size = callable_descriptor::CALLABLE_DESC_RUNTIME_CAPTURE_OFFSET
        + EVAL_DYNAMIC_CALLABLE_CAPTURE_BYTES;
    match module.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            emitter.instruction("sub sp, sp, #32");                             // reserve the context, callback and frame slots
            emitter.instruction("stp x29, x30, [sp, #16]");                     // preserve the caller frame around the runtime calls
            emitter.instruction("add x29, sp, #16");                            // establish a stable wrapper frame pointer
            emitter.instruction("str x0, [sp, #0]");                            // save the eval context capture
            emitter.instruction("str x1, [sp, #8]");                            // save the boxed callback capture
            emitter.instruction("mov x0, x1");                                  // retain the callback owned by the descriptor capture
            emitter.instruction("bl __rt_incref");                              // the descriptor's release retires this owner
            emitter.instruction(&format!("mov x0, #{size}"));                   // allocate the fixed descriptor plus two capture slots
            emitter.instruction("bl __rt_heap_alloc");                          // create the runtime descriptor block
            callable_descriptor::emit_copy_static_descriptor_to_runtime(emitter, "x0", descriptor_label);
            emitter.instruction("ldr x9, [sp, #0]");                            // reload the eval context capture
            abi::emit_store_to_address(emitter, "x9", "x0", dynamic_capture_offset(EVAL_DYNAMIC_CONTEXT_CAPTURE));
            emitter.instruction("ldr x9, [sp, #8]");                            // reload the retained boxed callback capture
            abi::emit_store_to_address(emitter, "x9", "x0", dynamic_capture_offset(EVAL_DYNAMIC_CALLBACK_CAPTURE));
            emitter.instruction("ldp x29, x30, [sp, #16]");                     // restore the caller frame
            emitter.instruction("add sp, sp, #32");                             // release the wrapper slots
            emitter.instruction("ret");                                         // return the owned adapter descriptor
        }
        crate::codegen::platform::Arch::X86_64 => {
            emitter.instruction("push rbp");                                    // preserve the caller frame pointer
            emitter.instruction("mov rbp, rsp");                                // establish a stable wrapper frame pointer
            emitter.instruction("sub rsp, 16");                                 // reserve the context and callback slots
            emitter.instruction("mov QWORD PTR [rbp - 8], rdi");                // save the eval context capture
            emitter.instruction("mov QWORD PTR [rbp - 16], rsi");               // save the boxed callback capture
            emitter.instruction("mov rax, rsi");                                // retain the callback owned by the descriptor capture
            emitter.instruction("call __rt_incref");                            // the descriptor's release retires this owner
            emitter.instruction(&format!("mov rax, {size}"));                   // allocate the fixed descriptor plus two capture slots
            emitter.instruction("call __rt_heap_alloc");                        // create the runtime descriptor block
            callable_descriptor::emit_copy_static_descriptor_to_runtime(emitter, "rax", descriptor_label);
            emitter.instruction("mov r10, QWORD PTR [rbp - 8]");                // reload the eval context capture
            abi::emit_store_to_address(emitter, "r10", "rax", dynamic_capture_offset(EVAL_DYNAMIC_CONTEXT_CAPTURE));
            emitter.instruction("mov r10, QWORD PTR [rbp - 16]");               // reload the retained boxed callback capture
            abi::emit_store_to_address(emitter, "r10", "rax", dynamic_capture_offset(EVAL_DYNAMIC_CALLBACK_CAPTURE));
            emitter.instruction("mov rsp, rbp");                                // release the wrapper slots
            emitter.instruction("pop rbp");                                     // restore the caller frame pointer
            emitter.instruction("ret");                                         // return the owned adapter descriptor
        }
    }
}

/// Emits the uniform invoker for descriptors that capture an eval callback value.
fn emit_eval_dynamic_callable_invoker(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
) {
    emitter.blank();
    emitter.comment("--- eval bridge: dynamic callable descriptor invoker ---");
    emitter.label(EVAL_DYNAMIC_CALLABLE_ENTRY_LABEL);
    emitter.instruction("ret");                                                 // direct entry calls are never used for eval dynamic descriptors
    emitter.label_global(EVAL_DYNAMIC_CALLABLE_INVOKER_LABEL);
    match module.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            emit_aarch64_eval_dynamic_callable_invoker(module, emitter, data);
        }
        crate::codegen::platform::Arch::X86_64 => {
            emit_x86_64_eval_dynamic_callable_invoker(module, emitter, data);
        }
    }
}

/// Emits the ARM64 body for eval dynamic callable descriptor invocation.
fn emit_aarch64_eval_dynamic_callable_invoker(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
) {
    let throwable_label = "__elephc_eval_dynamic_callable_throwable";
    let fatal_label = "__elephc_eval_dynamic_callable_fatal";
    let done_label = "__elephc_eval_dynamic_callable_done";
    let symbol = module
        .target
        .extern_symbol("__elephc_eval_callable_call_array");
    emitter.instruction("sub sp, sp, #64");                                     // reserve descriptor, arg-array, eval result, and saved frame slots
    emitter.instruction("stp x29, x30, [sp, #48]");                             // preserve the caller frame around the Rust callback
    emitter.instruction("add x29, sp, #48");                                    // establish a stable invoker frame pointer
    emitter.instruction("str x0, [sp, #0]");                                    // save the runtime callable descriptor pointer
    emitter.instruction("str x1, [sp, #8]");                                    // save the boxed Mixed invoker argument array
    emitter.instruction("str xzr, [sp, #16]");                                  // clear result kind and padding before the FFI call
    emitter.instruction("str xzr, [sp, #24]");                                  // clear result value pointer before the FFI call
    emitter.instruction("str xzr, [sp, #32]");                                  // clear result error pointer before the FFI call
    emitter.instruction("ldr x9, [sp, #0]");                                    // reload descriptor before reading eval captures
    emitter.instruction(&format!(                                               // pass the captured eval context as FFI argument 1
        "ldr x0, [x9, #{}]",
        dynamic_capture_offset(EVAL_DYNAMIC_CONTEXT_CAPTURE)
    ));
    emitter.instruction(&format!(                                               // pass the captured eval callback as FFI argument 2
        "ldr x1, [x9, #{}]",
        dynamic_capture_offset(EVAL_DYNAMIC_CALLBACK_CAPTURE)
    ));
    emitter.instruction("ldr x2, [sp, #8]");                                    // pass the boxed Mixed invoker argument array
    emitter.instruction("add x3, sp, #16");                                     // pass writable eval result storage
    abi::emit_call_label(emitter, &symbol);
    emitter.instruction("cmp w0, #0");                                          // did magician complete callback dispatch successfully?
    emitter.instruction(&format!("b.eq {}", done_label));                       // return the boxed result on success
    emitter.instruction("cmp w0, #3");                                          // status 3 means an eval Throwable escaped
    emitter.instruction(&format!("b.eq {}", throwable_label));                  // publish the Throwable through native unwinding
    emitter.label(fatal_label);
    emit_aarch64_eval_dynamic_callable_fatal(emitter, data);
    emitter.label(throwable_label);
    emitter.instruction("ldr x0, [sp, #32]");                                   // load the boxed Throwable returned by magician
    abi::emit_call_label(emitter, "__rt_throwable_take_boxed");
    abi::emit_store_reg_to_symbol(emitter, "x0", "_exc_value", 0);
    emitter.instruction("bl __rt_throw_current");                               // enter the native Throwable unwinder
    emitter.label(done_label);
    emitter.instruction("ldr x0, [sp, #24]");                                   // return the boxed Mixed callback result
    emitter.instruction("ldp x29, x30, [sp, #48]");                             // restore the caller frame
    emitter.instruction("add sp, sp, #64");                                     // release invoker scratch storage
    emitter.instruction("ret");                                                 // return to the descriptor invoker caller
}

/// Emits the x86_64 body for eval dynamic callable descriptor invocation.
fn emit_x86_64_eval_dynamic_callable_invoker(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
) {
    let throwable_label = "__elephc_eval_dynamic_callable_throwable_x";
    let fatal_label = "__elephc_eval_dynamic_callable_fatal_x";
    let done_label = "__elephc_eval_dynamic_callable_done_x";
    let symbol = module
        .target
        .extern_symbol("__elephc_eval_callable_call_array");
    emitter.instruction("push rbp");                                            // preserve the caller frame pointer
    emitter.instruction("mov rbp, rsp");                                        // establish a stable invoker frame pointer
    emitter.instruction("sub rsp, 64");                                         // reserve descriptor, arg-array, and eval result slots
    emitter.instruction("mov QWORD PTR [rbp - 8], rdi");                        // save the runtime callable descriptor pointer
    emitter.instruction("mov QWORD PTR [rbp - 16], rsi");                       // save the boxed Mixed invoker argument array
    emitter.instruction("mov QWORD PTR [rbp - 48], 0");                         // clear result kind and padding before the FFI call
    emitter.instruction("mov QWORD PTR [rbp - 40], 0");                         // clear result value pointer before the FFI call
    emitter.instruction("mov QWORD PTR [rbp - 32], 0");                         // clear result error pointer before the FFI call
    emitter.instruction("mov r9, QWORD PTR [rbp - 8]");                         // reload descriptor before reading eval captures
    emitter.instruction(&format!(                                               // pass the captured eval context as FFI argument 1
        "mov rdi, QWORD PTR [r9 + {}]",
        dynamic_capture_offset(EVAL_DYNAMIC_CONTEXT_CAPTURE)
    ));
    emitter.instruction(&format!(                                               // pass the captured eval callback as FFI argument 2
        "mov rsi, QWORD PTR [r9 + {}]",
        dynamic_capture_offset(EVAL_DYNAMIC_CALLBACK_CAPTURE)
    ));
    emitter.instruction("mov rdx, QWORD PTR [rbp - 16]");                       // pass the boxed Mixed invoker argument array
    emitter.instruction("lea rcx, [rbp - 48]");                                 // pass writable eval result storage
    abi::emit_call_label(emitter, &symbol);
    emitter.instruction("test eax, eax");                                       // did magician complete callback dispatch successfully?
    emitter.instruction(&format!("je {}", done_label));                         // return the boxed result on success
    emitter.instruction("cmp eax, 3");                                          // status 3 means an eval Throwable escaped
    emitter.instruction(&format!("je {}", throwable_label));                    // publish the Throwable through native unwinding
    emitter.label(fatal_label);
    emit_x86_64_eval_dynamic_callable_fatal(emitter, data);
    emitter.label(throwable_label);
    emitter.instruction("mov rax, QWORD PTR [rbp - 32]");                       // load the boxed Throwable returned by magician
    abi::emit_call_label(emitter, "__rt_throwable_take_boxed");
    abi::emit_store_reg_to_symbol(emitter, "rax", "_exc_value", 0);
    emitter.instruction("call __rt_throw_current");                             // enter the native Throwable unwinder
    emitter.label(done_label);
    emitter.instruction("mov rax, QWORD PTR [rbp - 40]");                       // return the boxed Mixed callback result
    emitter.instruction("mov rsp, rbp");                                        // discard invoker scratch storage
    emitter.instruction("pop rbp");                                             // restore the caller frame pointer
    emitter.instruction("ret");                                                 // return to the descriptor invoker caller
}

/// Returns the byte offset for one dynamic eval callable descriptor capture.
fn dynamic_capture_offset(index: usize) -> usize {
    callable_descriptor::CALLABLE_DESC_RUNTIME_CAPTURE_OFFSET + index * 16
}

/// Emits an ARM64 fatal diagnostic for failed eval callback dispatch.
fn emit_aarch64_eval_dynamic_callable_fatal(emitter: &mut Emitter, data: &mut DataSection) {
    let (message_label, message_len) =
        data.add_string(b"Fatal error: eval callback dispatch failed\n");
    emitter.instruction("mov x0, #2");                                          // write the eval callback diagnostic to stderr
    emitter.adrp("x1", &message_label);
    emitter.add_lo12("x1", "x1", &message_label);
    emitter.instruction(&format!("mov x2, #{}", message_len));                  // pass the diagnostic byte length to write
    emitter.syscall(4);
    abi::emit_exit(emitter, 1);
}

/// Emits an x86_64 fatal diagnostic for failed eval callback dispatch.
fn emit_x86_64_eval_dynamic_callable_fatal(emitter: &mut Emitter, data: &mut DataSection) {
    let (message_label, message_len) =
        data.add_string(b"Fatal error: eval callback dispatch failed\n");
    emitter.instruction("mov edi, 2");                                          // write the eval callback diagnostic to stderr
    abi::emit_symbol_address(emitter, "rsi", &message_label);
    emitter.instruction(&format!("mov edx, {}", message_len));                  // pass the diagnostic byte length to write
    emitter.instruction("mov eax, 1");                                          // Linux x86_64 syscall 1 = write
    emitter.instruction("syscall");                                             // emit the fatal diagnostic before terminating
    abi::emit_exit(emitter, 1);
}

/// Builds descriptor cases for user functions visible as eval string callables.
fn eval_user_function_callable_cases(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
) -> Vec<RuntimeCallableCase> {
    let mut functions = eval_user_function_sigs(module);
    functions.sort_by(|left, right| left.0.cmp(&right.0));
    let mut cases = Vec::with_capacity(functions.len());
    for (name, sig, bridge_supported) in functions {
        if bridge_supported {
            continue;
        }
        let case_sig = callable_wrapper_sig(&sig);
        let owns_string_return = module.functions.iter().find(|function| function.name == name)
            .is_some_and(super::runtime_callable_invoker::function_returns_owned_string);
        let invoker_label =
            emit_eval_runtime_callable_invoker_inline(module, emitter, data, state, &case_sig, &[], owns_string_return, None);
        let descriptor_label = callable_descriptor::static_descriptor_with_optional_invoker_meta(
            data,
            &function_symbol(&name),
            Some(&name),
            callable_descriptor::CALLABLE_DESC_KIND_FUNCTION,
            Some(&case_sig),
            &[],
            &[],
            CallableDescriptorInvocation::named(CallableDescriptorShape::Function, &name),
            Some(&invoker_label),
        );
        cases.push(RuntimeCallableCase {
            descriptor_label,
            php_name: Some(name),
        });
    }
    cases
}

/// Collects user function signatures available to eval string-callable descriptors.
fn eval_user_function_sigs(module: &Module) -> Vec<(String, FunctionSig, bool)> {
    let mut functions = module
        .functions
        .iter()
        .filter(|function| {
            !function.flags.is_main && !function.name.starts_with("_class_propinit_")
        })
        .map(|function| {
            (
                function.name.clone(),
                super::lower_inst::function_signature_from_eir(function),
                eval_native_function_bridge_supported(function),
            )
        })
        .collect::<Vec<_>>();
    for group in super::function_variants::collect_dispatch_groups(module) {
        if functions.iter().any(|(name, _, _)| name == &group.name) {
            continue;
        }
        if let Some(function) = super::function_variants::variant_callee_for_group(module, &group.name)
        {
            functions.push((
                group.name.clone(),
                super::lower_inst::function_signature_from_eir(function),
                eval_native_function_bridge_supported(function),
            ));
        }
    }
    functions
}

/// Builds descriptor cases for emitted public instance methods visible to eval.
fn eval_instance_method_callable_cases(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
) -> Vec<EvalInstanceMethodCallableCase> {
    eval_instance_callable_cases(
        module,
        emitter,
        data,
        state,
        EvalInstanceCallableShape::InstanceMethod,
        |_| true,
    )
}

/// Builds descriptor cases for emitted public `__invoke` methods visible to eval.
fn eval_invokable_object_callable_cases(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
) -> Vec<EvalInstanceMethodCallableCase> {
    eval_instance_callable_cases(
        module,
        emitter,
        data,
        state,
        EvalInstanceCallableShape::ObjectInvoke,
        |method_name| php_symbol_key(method_name) == "__invoke",
    )
}

/// Builds receiver-bound descriptor cases for public emitted instance methods.
fn eval_instance_callable_cases(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
    shape: EvalInstanceCallableShape,
    include_method: impl Fn(&str) -> bool,
) -> Vec<EvalInstanceMethodCallableCase> {
    let emitted_methods = eval_eir_class_method_keys(module);
    let mut candidates = Vec::new();
    for (class_name, class_info) in &module.class_infos {
        for (method_name, sig) in &class_info.methods {
            if !include_method(method_name) {
                continue;
            }
            if eval_native_instance_method_bridge_supported(class_info, method_name, sig) {
                continue;
            }
            if !class_info
                .method_visibilities
                .get(method_name)
                .is_some_and(|visibility| matches!(visibility, Visibility::Public))
            {
                continue;
            }
            let method_key = php_symbol_key(method_name);
            let impl_class = class_info
                .method_impl_classes
                .get(&method_key)
                .map(String::as_str)
                .unwrap_or(class_name);
            if emitted_methods.contains(&(impl_class.to_string(), method_key.clone(), false)) {
                candidates.push((
                    class_name.clone(),
                    class_info.class_id,
                    method_name.clone(),
                    method_key,
                    impl_class.to_string(),
                    sig.clone(),
                ));
            }
        }
    }
    candidates.sort_by(|left, right| (&left.0, &left.2).cmp(&(&right.0, &right.2)));
    candidates
        .into_iter()
        .map(
            |(class_name, class_id, method_name, method_key, impl_class, sig)| {
                let case = receiver_bound_instance_method_case(
                    module,
                    emitter,
                    data,
                    state,
                    &class_name,
                    &impl_class,
                    &method_name,
                    &method_key,
                    &sig,
                    shape,
                );
                EvalInstanceMethodCallableCase {
                    class_id,
                    method_name,
                    case,
                }
            },
        )
        .collect()
}

/// Builds descriptor cases for emitted public static methods visible to eval.
fn eval_static_method_callable_cases(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
) -> Vec<RuntimeStaticMethodCallableCase> {
    let emitted_methods = eval_eir_class_method_keys(module);
    let mut candidates = Vec::new();
    for (class_name, class_info) in &module.class_infos {
        for (method_name, sig) in &class_info.static_methods {
            if eval_native_static_method_bridge_supported(class_info, method_name, sig) {
                continue;
            }
            if !class_info
                .static_method_visibilities
                .get(method_name)
                .is_some_and(|visibility| matches!(visibility, Visibility::Public))
            {
                continue;
            }
            let method_key = php_symbol_key(method_name);
            let impl_class = class_info
                .static_method_impl_classes
                .get(&method_key)
                .map(String::as_str)
                .unwrap_or(class_name);
            if emitted_methods.contains(&(impl_class.to_string(), method_key.clone(), true)) {
                candidates.push((
                    class_name.clone(),
                    method_name.clone(),
                    method_key,
                    impl_class.to_string(),
                    class_info.class_id,
                    sig.clone(),
                ));
            }
        }
    }
    candidates.sort_by(|left, right| (&left.0, &left.1).cmp(&(&right.0, &right.1)));
    candidates
        .into_iter()
        .map(
            |(class_name, method_name, method_key, impl_class, class_id, sig)| {
                let wrapper_sig = callable_dispatch::static_method_runtime_wrapper_sig(&sig);
                let entry_label = emit_eval_static_method_descriptor_entry_wrapper(
                    emitter,
                    state,
                    &impl_class,
                    &method_key,
                    &wrapper_sig,
                    class_id,
                );
                let php_name = format!("{}::{}", class_name, method_name);
                let owns_string_return = super::runtime_callable_invoker::method_returns_owned_string(
                    module, &impl_class, &method_key, true,
                );
                let invoker_label =
                    emit_eval_runtime_callable_invoker_inline(module, emitter, data, state, &wrapper_sig, &[], owns_string_return, Some(&impl_class));
                let descriptor_label =
                    callable_descriptor::static_descriptor_with_optional_invoker_meta(
                        data,
                        &entry_label,
                        Some(&php_name),
                        callable_descriptor::CALLABLE_DESC_KIND_STATIC_METHOD,
                        Some(&wrapper_sig),
                        &[],
                        &[],
                        CallableDescriptorInvocation::method(
                            CallableDescriptorShape::StaticMethod,
                            Some(class_name.clone()),
                            method_name.as_str(),
                        ),
                        Some(&invoker_label),
                    );
                RuntimeStaticMethodCallableCase {
                    class_name,
                    method_name,
                    case: RuntimeCallableCase {
                        descriptor_label,
                        php_name: Some(php_name),
                    },
                }
            },
        )
        .collect()
}

/// Returns class-method symbols backed by lowered EIR functions.
fn eval_eir_class_method_keys(module: &Module) -> HashSet<(String, String, bool)> {
    module
        .class_methods
        .iter()
        .filter_map(|function| {
            let (class_name, method_name) = function.name.rsplit_once("::")?;
            Some((
                class_name.to_string(),
                php_symbol_key(method_name),
                function.flags.is_static,
            ))
        })
        .collect()
}

/// Builds a receiver-bound descriptor case for one public instance method.
#[allow(clippy::too_many_arguments)]
fn receiver_bound_instance_method_case(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
    class_name: &str,
    impl_class: &str,
    method_name: &str,
    method_key: &str,
    sig: &FunctionSig,
    shape: EvalInstanceCallableShape,
) -> RuntimeCallableCase {
    let case_sig = callable_wrapper_sig(sig);
    let hidden_name = unique_hidden_param(EVAL_RECEIVER_CAPTURE_PARAM, &case_sig);
    let capture_ty = PhpType::Object(class_name.to_string());
    let captures = vec![(hidden_name.clone(), capture_ty.clone(), false)];
    let entry_label = emit_eval_instance_method_descriptor_entry_wrapper(
        emitter,
        state,
        impl_class,
        method_key,
        &case_sig,
    );
    let owns_string_return = super::runtime_callable_invoker::method_returns_owned_string(
        module, impl_class, method_key, false,
    );
    let invoker_label =
        emit_eval_runtime_callable_invoker_inline(module, emitter, data, state, &case_sig, &captures, owns_string_return, Some(impl_class));
    let (kind, invocation_shape) = match shape {
        EvalInstanceCallableShape::ObjectInvoke => (
            callable_descriptor::CALLABLE_DESC_KIND_OBJECT_INVOKE,
            CallableDescriptorShape::ObjectInvoke,
        ),
        EvalInstanceCallableShape::InstanceMethod => (
            callable_descriptor::CALLABLE_DESC_KIND_INSTANCE_METHOD,
            CallableDescriptorShape::InstanceMethod,
        ),
    };
    let php_name = format!("{}::{}", class_name, method_name);
    let descriptor_label = callable_descriptor::static_descriptor_with_optional_invoker_meta(
        data,
        &entry_label,
        Some(&php_name),
        kind,
        Some(&case_sig),
        &captures,
        &captures,
        CallableDescriptorInvocation::method(
            invocation_shape,
            Some(class_name.to_string()),
            method_name,
        ),
        Some(&invoker_label),
    );
    RuntimeCallableCase {
        descriptor_label,
        php_name: Some(php_name),
    }
}

/// Emits a descriptor invoker out of line, after the function that first needed it.
///
/// `current_class` is the class that DECLARES the callee, which is the scope `self::`,
/// `static::` and `parent::` resolve in when the invoker materializes a parameter default.
#[allow(clippy::too_many_arguments)]
fn emit_eval_runtime_callable_invoker_inline(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    state: &mut EvalCallableEmitState,
    sig: &FunctionSig,
    captures: &[(String, PhpType, bool)],
    owns_string_return: bool,
    current_class: Option<&str>,
) -> String {
    if let Some(label) = state.runtime_callable_invoker(sig, captures, owns_string_return, current_class) {
        return label;
    }
    state.argument_normalizer_needed |=
        super::runtime_callable_invoker::needs_callable_argument_normalizer(sig);
    let defaults = super::runtime_callable_invoker::resolve_invoker_defaults(
        module,
        current_class,
        sig,
    );
    let invoker = RuntimeCallableInvoker {
        label: PENDING_INVOKER_LABEL,
        sig,
        captures,
        mbstring_operation: None,
        mbstring_variable_ref_warnings: false,
        owns_string_return,
        php_return_status: true,
        defaults: &defaults,
    };
    // See `Emitter::begin_out_of_line` for the branch-range failure that splicing caused.
    let scope = emitter.begin_out_of_line();
    super::runtime_callable_invoker::emit_runtime_callable_invoker(emitter, data, &invoker);
    let body = emitter.end_detached(scope);
    // Most callees share a few shapes: an `eval()` program emitted 633 of these invokers with
    // 148 distinct bodies. The invoker emitter keeps no state outside its text, and its data
    // entries are content-deduplicated strings and floats, so a body whose text matches an
    // earlier one is dropped for that one's label. The signature cache above answers the
    // same signature again without emitting at all.
    let label = state.emitted_invoker(body, |body| emitter.push_out_of_line(body));
    state.cache_runtime_callable_invoker(sig, captures, owns_string_return, current_class, label.clone());
    label
}

/// Returns a hidden receiver parameter name that cannot collide with visible parameters.
fn unique_hidden_param(base: &str, sig: &FunctionSig) -> String {
    if !sig.params.iter().any(|(name, _)| name == base) {
        return base.to_string();
    }
    let mut index = 0usize;
    loop {
        let candidate = format!("{}_{}", base, index);
        if !sig.params.iter().any(|(name, _)| name == &candidate) {
            return candidate;
        }
        index += 1;
    }
}

/// Emits an entry wrapper that receives visible args followed by the captured receiver.
fn emit_eval_instance_method_descriptor_entry_wrapper(
    emitter: &mut Emitter,
    state: &mut EvalCallableEmitState,
    class_name: &str,
    method_key: &str,
    sig: &FunctionSig,
) -> String {
    let visible_arg_types = descriptor_visible_arg_types(sig);
    let wrapper_label = state.next_label("callable_instance_method");
    // Out of line, not spliced into the caller: see `Emitter::begin_out_of_line`. The label is
    // referenced only from a static descriptor in data, so its position is free.
    let scope = emitter.begin_out_of_line();
    emitter.label(&wrapper_label);
    emit_eval_instance_method_descriptor_entry_wrapper_body(
        emitter,
        class_name,
        method_key,
        &visible_arg_types,
    );
    emitter.end_out_of_line(scope);
    wrapper_label
}

/// Emits an entry wrapper that prepends a concrete called-class id before calling a static method.
fn emit_eval_static_method_descriptor_entry_wrapper(
    emitter: &mut Emitter,
    state: &mut EvalCallableEmitState,
    impl_class: &str,
    method_key: &str,
    sig: &FunctionSig,
    called_class_id: u64,
) -> String {
    let visible_arg_types = descriptor_visible_arg_types(sig);
    let wrapper_label = state.next_label("static_method_descriptor_entry");
    // Out of line, not spliced into the caller: see `Emitter::begin_out_of_line`. The label is
    // referenced only from a static descriptor in data, so its position is free.
    let scope = emitter.begin_out_of_line();
    emitter.label(&wrapper_label);
    emit_eval_static_method_descriptor_entry_wrapper_body(
        emitter,
        impl_class,
        method_key,
        &visible_arg_types,
        called_class_id,
    );
    emitter.end_out_of_line(scope);
    wrapper_label
}

/// Returns codegen-representation parameter types for a descriptor entry wrapper.
fn descriptor_visible_arg_types(sig: &FunctionSig) -> Vec<PhpType> {
    sig.params.iter().map(|(_, ty)| ty.codegen_repr()).collect()
}

/// Emits a descriptor entry wrapper body by reordering visible args after the receiver.
fn emit_eval_instance_method_descriptor_entry_wrapper_body(
    emitter: &mut Emitter,
    class_name: &str,
    method_key: &str,
    visible_arg_types: &[PhpType],
) {
    let receiver_ty = descriptor_receiver_type(class_name);
    let incoming_types = descriptor_entry_incoming_types(visible_arg_types, &receiver_ty);
    let actual_types = descriptor_entry_actual_types(visible_arg_types, &receiver_ty);
    let incoming_assignments =
        abi::build_outgoing_arg_assignments_for_target(emitter.target, &incoming_types, 0);
    let actual_assignments =
        abi::build_outgoing_arg_assignments_for_target(emitter.target, &actual_types, 0);
    let (incoming_stack_offsets, _) = descriptor_entry_stack_offsets(&incoming_assignments);
    let (actual_stack_offsets, actual_overflow_bytes) =
        descriptor_entry_stack_offsets(&actual_assignments);
    let actual_stack_pad_bytes = abi::outgoing_call_stack_pad_bytes(emitter.target, actual_overflow_bytes);
    let frame_size = descriptor_entry_frame_size(incoming_types.len());

    abi::emit_frame_prologue(emitter, frame_size);
    for (idx, (ty, assignment)) in incoming_types
        .iter()
        .zip(incoming_assignments.iter())
        .enumerate()
    {
        store_descriptor_entry_incoming_arg(
            emitter,
            ty,
            assignment,
            descriptor_entry_slot_offset(idx),
            incoming_stack_offsets[idx],
        );
    }
    if actual_overflow_bytes > 0 {
        abi::emit_reserve_temporary_stack(emitter, actual_overflow_bytes);
    }
    for (idx, (ty, assignment)) in actual_types
        .iter()
        .zip(actual_assignments.iter())
        .enumerate()
    {
        let source_idx = if idx == 0 {
            visible_arg_types.len()
        } else {
            idx - 1
        };
        load_descriptor_entry_actual_arg(
            emitter,
            ty,
            assignment,
            descriptor_entry_slot_offset(source_idx),
            actual_stack_offsets[idx],
        );
    }
    if actual_stack_pad_bytes > 0 {
        abi::emit_reserve_temporary_stack(emitter, actual_stack_pad_bytes);
    }
    abi::emit_call_label(emitter, &method_symbol(class_name, method_key));
    if actual_stack_pad_bytes > 0 {
        abi::emit_release_temporary_stack(emitter, actual_stack_pad_bytes);
    }
    if actual_overflow_bytes > 0 {
        abi::emit_release_temporary_stack(emitter, actual_overflow_bytes);
    }
    abi::emit_frame_restore(emitter, frame_size);
    abi::emit_return(emitter);
}

/// Emits a static descriptor entry wrapper body by prepending the called-class id.
fn emit_eval_static_method_descriptor_entry_wrapper_body(
    emitter: &mut Emitter,
    impl_class: &str,
    method_key: &str,
    visible_arg_types: &[PhpType],
    called_class_id: u64,
) {
    let actual_types = {
        let mut types = Vec::with_capacity(visible_arg_types.len() + 1);
        types.push(PhpType::Int);
        types.extend_from_slice(visible_arg_types);
        types
    };
    let incoming_assignments =
        abi::build_outgoing_arg_assignments_for_target(emitter.target, visible_arg_types, 0);
    let actual_assignments =
        abi::build_outgoing_arg_assignments_for_target(emitter.target, &actual_types, 0);
    let (incoming_stack_offsets, _) = descriptor_entry_stack_offsets(&incoming_assignments);
    let (actual_stack_offsets, actual_overflow_bytes) =
        descriptor_entry_stack_offsets(&actual_assignments);
    let actual_stack_pad_bytes = abi::outgoing_call_stack_pad_bytes(emitter.target, actual_overflow_bytes);
    let frame_size = descriptor_entry_frame_size(visible_arg_types.len());

    abi::emit_frame_prologue(emitter, frame_size);
    for (idx, (ty, assignment)) in visible_arg_types
        .iter()
        .zip(incoming_assignments.iter())
        .enumerate()
    {
        store_descriptor_entry_incoming_arg(
            emitter,
            ty,
            assignment,
            descriptor_entry_slot_offset(idx),
            incoming_stack_offsets[idx],
        );
    }
    if actual_overflow_bytes > 0 {
        abi::emit_reserve_temporary_stack(emitter, actual_overflow_bytes);
    }
    for (idx, (ty, assignment)) in actual_types
        .iter()
        .zip(actual_assignments.iter())
        .enumerate()
    {
        if idx == 0 {
            load_descriptor_entry_static_class_id(
                emitter,
                called_class_id,
                assignment,
                actual_stack_offsets[idx],
            );
        } else {
            load_descriptor_entry_actual_arg(
                emitter,
                ty,
                assignment,
                descriptor_entry_slot_offset(idx - 1),
                actual_stack_offsets[idx],
            );
        }
    }
    if actual_stack_pad_bytes > 0 {
        abi::emit_reserve_temporary_stack(emitter, actual_stack_pad_bytes);
    }
    abi::emit_call_label(emitter, &static_method_symbol(impl_class, method_key));
    if actual_stack_pad_bytes > 0 {
        abi::emit_release_temporary_stack(emitter, actual_stack_pad_bytes);
    }
    if actual_overflow_bytes > 0 {
        abi::emit_release_temporary_stack(emitter, actual_overflow_bytes);
    }
    abi::emit_frame_restore(emitter, frame_size);
    abi::emit_return(emitter);
}

/// Loads the concrete called-class id into a descriptor wrapper's outgoing ABI slot.
fn load_descriptor_entry_static_class_id(
    emitter: &mut Emitter,
    class_id: u64,
    assignment: &abi::OutgoingArgAssignment,
    stack_offset: Option<usize>,
) {
    let reg = if assignment.in_register() {
        abi::int_arg_reg_name(emitter.target, assignment.start_reg)
    } else {
        abi::secondary_scratch_reg(emitter)
    };
    abi::emit_load_int_immediate(emitter, reg, class_id as i64);
    if let Some(out_offset) = stack_offset {
        abi::emit_store_to_sp(emitter, reg, out_offset);
    }
}

/// Returns the runtime receiver type threaded through the descriptor entry wrapper.
fn descriptor_receiver_type(class_name: &str) -> PhpType {
    PhpType::Object(class_name.to_string())
}

/// Returns the wrapper incoming argument order: visible args followed by receiver.
fn descriptor_entry_incoming_types(
    visible_arg_types: &[PhpType],
    receiver_ty: &PhpType,
) -> Vec<PhpType> {
    let mut types = visible_arg_types.to_vec();
    types.push(receiver_ty.clone());
    types
}

/// Returns the real method ABI argument order: receiver followed by visible args.
fn descriptor_entry_actual_types(
    visible_arg_types: &[PhpType],
    receiver_ty: &PhpType,
) -> Vec<PhpType> {
    let mut types = Vec::with_capacity(visible_arg_types.len() + 1);
    types.push(receiver_ty.clone());
    types.extend_from_slice(visible_arg_types);
    types
}

/// Returns an aligned frame size for descriptor entry wrapper spill slots plus footer.
fn descriptor_entry_frame_size(slot_count: usize) -> usize {
    align16((slot_count + 1) * 16)
}

/// Returns the frame offset for a descriptor entry wrapper spill slot.
fn descriptor_entry_slot_offset(idx: usize) -> usize {
    (idx + 1) * 16
}

/// Returns the local/outgoing byte size used for one descriptor wrapper argument.
fn descriptor_entry_arg_slot_size(ty: &PhpType) -> usize {
    match ty.codegen_repr() {
        PhpType::Void | PhpType::Never => 0,
        _ => 16,
    }
}

/// Returns stack offsets for ABI assignments that overflow their target registers.
fn descriptor_entry_stack_offsets(
    assignments: &[abi::OutgoingArgAssignment],
) -> (Vec<Option<usize>>, usize) {
    let mut offsets = vec![None; assignments.len()];
    let mut next_offset = 0usize;
    for (idx, assignment) in assignments.iter().enumerate() {
        if assignment.in_register() {
            continue;
        }
        offsets[idx] = Some(next_offset);
        next_offset += descriptor_entry_arg_slot_size(&assignment.ty);
    }
    (offsets, next_offset)
}

/// Converts a descriptor overflow offset into a caller-stack frame offset.
fn descriptor_entry_caller_stack_offset(emitter: &Emitter, stack_offset: usize) -> usize {
    let cursor = abi::IncomingArgCursor::for_target(emitter.target, 0);
    cursor.caller_stack_offset + stack_offset
}

/// Returns integer scratch registers that cannot overlap live descriptor argument registers.
fn descriptor_entry_int_spill_pair(emitter: &Emitter) -> (&'static str, &'static str) {
    let lo_reg = abi::secondary_scratch_reg(emitter);
    let hi_reg = match emitter.target.arch {
        crate::codegen::platform::Arch::AArch64 => abi::tertiary_scratch_reg(emitter),
        crate::codegen::platform::Arch::X86_64 => "r11",
    };
    (lo_reg, hi_reg)
}

/// Stores one incoming descriptor entry argument into its spill slot.
fn store_descriptor_entry_incoming_arg(
    emitter: &mut Emitter,
    ty: &PhpType,
    assignment: &abi::OutgoingArgAssignment,
    offset: usize,
    stack_offset: Option<usize>,
) {
    match ty.codegen_repr() {
        PhpType::Float => {
            let reg = if assignment.in_register() {
                abi::float_arg_reg_name(emitter.target, assignment.start_reg)
            } else {
                let caller_offset =
                    descriptor_entry_caller_stack_offset(emitter, stack_offset.expect("stack offset"));
                let spill_reg = abi::float_spill_scratch_reg(emitter.target);
                abi::load_from_caller_stack(emitter, spill_reg, caller_offset);
                spill_reg
            };
            abi::store_at_offset(emitter, reg, offset);
        }
        PhpType::Str => {
            let (ptr_reg, len_reg) = if assignment.in_register() {
                (
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg),
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg + 1),
                )
            } else {
                let caller_offset =
                    descriptor_entry_caller_stack_offset(emitter, stack_offset.expect("stack offset"));
                let (ptr_spill_reg, len_spill_reg) = descriptor_entry_int_spill_pair(emitter);
                abi::load_from_caller_stack(emitter, ptr_spill_reg, caller_offset);
                abi::load_from_caller_stack(emitter, len_spill_reg, caller_offset + 8);
                (ptr_spill_reg, len_spill_reg)
            };
            abi::store_at_offset(emitter, ptr_reg, offset);
            abi::store_at_offset(emitter, len_reg, offset - 8);
        }
        PhpType::TaggedScalar => {
            let (payload_reg, tag_reg) = if assignment.in_register() {
                (
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg),
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg + 1),
                )
            } else {
                let caller_offset =
                    descriptor_entry_caller_stack_offset(emitter, stack_offset.expect("stack offset"));
                let (payload_spill_reg, tag_spill_reg) = descriptor_entry_int_spill_pair(emitter);
                abi::load_from_caller_stack(emitter, payload_spill_reg, caller_offset);
                abi::load_from_caller_stack(emitter, tag_spill_reg, caller_offset + 8);
                (payload_spill_reg, tag_spill_reg)
            };
            abi::store_at_offset(emitter, payload_reg, offset);
            abi::store_at_offset(emitter, tag_reg, offset - 8);
        }
        PhpType::Void | PhpType::Never => {}
        _ => {
            let reg = if assignment.in_register() {
                abi::int_arg_reg_name(emitter.target, assignment.start_reg)
            } else {
                let caller_offset =
                    descriptor_entry_caller_stack_offset(emitter, stack_offset.expect("stack offset"));
                let spill_reg = abi::secondary_scratch_reg(emitter);
                abi::load_from_caller_stack(emitter, spill_reg, caller_offset);
                spill_reg
            };
            abi::store_at_offset(emitter, reg, offset);
        }
    }
}

/// Loads one spilled descriptor entry argument into its real method ABI assignment.
fn load_descriptor_entry_actual_arg(
    emitter: &mut Emitter,
    ty: &PhpType,
    assignment: &abi::OutgoingArgAssignment,
    offset: usize,
    stack_offset: Option<usize>,
) {
    match ty.codegen_repr() {
        PhpType::Float => {
            let reg = if assignment.in_register() {
                abi::float_arg_reg_name(emitter.target, assignment.start_reg)
            } else {
                abi::float_spill_scratch_reg(emitter.target)
            };
            abi::load_at_offset(emitter, reg, offset);
            if let Some(out_offset) = stack_offset {
                abi::emit_store_to_sp(emitter, reg, out_offset);
            }
        }
        PhpType::Str => {
            let (ptr_reg, len_reg) = if assignment.in_register() {
                (
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg),
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg + 1),
                )
            } else {
                descriptor_entry_int_spill_pair(emitter)
            };
            abi::load_at_offset(emitter, ptr_reg, offset);
            abi::load_at_offset(emitter, len_reg, offset - 8);
            if let Some(out_offset) = stack_offset {
                abi::emit_store_to_sp(emitter, ptr_reg, out_offset);
                abi::emit_store_to_sp(emitter, len_reg, out_offset + 8);
            }
        }
        PhpType::TaggedScalar => {
            let (payload_reg, tag_reg) = if assignment.in_register() {
                (
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg),
                    abi::int_arg_reg_name(emitter.target, assignment.start_reg + 1),
                )
            } else {
                descriptor_entry_int_spill_pair(emitter)
            };
            abi::load_at_offset(emitter, payload_reg, offset);
            abi::load_at_offset(emitter, tag_reg, offset - 8);
            if let Some(out_offset) = stack_offset {
                abi::emit_store_to_sp(emitter, payload_reg, out_offset);
                abi::emit_store_to_sp(emitter, tag_reg, out_offset + 8);
            }
        }
        PhpType::Void | PhpType::Never => {}
        _ => {
            let reg = if assignment.in_register() {
                abi::int_arg_reg_name(emitter.target, assignment.start_reg)
            } else {
                abi::secondary_scratch_reg(emitter)
            };
            abi::load_at_offset(emitter, reg, offset);
            if let Some(out_offset) = stack_offset {
                abi::emit_store_to_sp(emitter, reg, out_offset);
            }
        }
    }
}

/// Rounds `value` up to a 16-byte multiple.
fn align16(value: usize) -> usize {
    (value + 15) & !15
}

/// Converts the ARM64 boxed eval argument slot into a callable descriptor pointer.
pub(super) fn emit_aarch64_cast_eval_callable_arg(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    support: &EvalCallableDescriptorSupport,
    label_prefix: &str,
    fail_label: &str,
    context_offset: i64,
    source_offset: i64,
) {
    let string_label = format!("{}_callable_string", label_prefix);
    let array_label = format!("{}_callable_array", label_prefix);
    let object_label = format!("{}_callable_object", label_prefix);
    let descriptor_label = format!("{}_callable_descriptor", label_prefix);
    let dynamic_label = format!("{}_callable_dynamic", label_prefix);
    let miss_label = if support.has_dynamic_descriptor() {
        dynamic_label.as_str()
    } else {
        fail_label
    };
    emitter.instruction(&format!("ldr x0, [x29, #{}]", source_offset));         // reload the boxed eval value for callable validation
    emitter.instruction("bl __rt_mixed_unbox");                                 // expose the eval callable tag and payload words
    emitter.instruction("cmp x0, #1");                                          // runtime tag 1 means a string callable name
    emitter.instruction(&format!("b.eq {}", string_label));                     // resolve string callables through descriptor metadata
    emitter.instruction("cmp x0, #4");                                          // runtime tag 4 means an indexed callable array
    abi::emit_branch_if_equal_wide(emitter, &array_label);                      // resolve indexed callable arrays past the string-name lookup table
    emitter.instruction("cmp x0, #5");                                          // runtime tag 5 means an associative callable array
    abi::emit_branch_if_equal_wide(emitter, &array_label);                      // resolve callable arrays with numeric keys past that table
    emitter.instruction("cmp x0, #6");                                          // runtime tag 6 means an invokable object candidate
    abi::emit_branch_if_equal_wide(emitter, &object_label);                     // resolve invokable objects past the string and array lookups
    emitter.instruction("cmp x0, #10");                                         // runtime tag 10 is an AOT first-class callable descriptor
    abi::emit_branch_if_equal_wide(emitter, &descriptor_label);                 // preserve the already-valid callable ABI payload
    abi::emit_jump(emitter, miss_label);
    emitter.label(&descriptor_label);
    emitter.instruction("mov x0, x1");                                          // return the unboxed callable descriptor pointer
    emitter.instruction("bl __rt_incref");                                      // every cast path hands back an owned descriptor; the box keeps its own
    abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    emitter.label(&string_label);
    abi::emit_push_reg_pair(emitter, "x1", "x2");
    emit_eval_string_callable_descriptor_lookup(
        module,
        emitter,
        data,
        support,
        label_prefix,
        miss_label,
        "x0",
    );
    abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    emitter.label(&array_label);
    emit_aarch64_eval_callable_array_selector_slots(module, emitter, source_offset);
    emit_eval_callable_array_descriptor_lookup(
        emitter,
        data,
        support,
        label_prefix,
        miss_label,
        "x0",
    );
    abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    emitter.label(&object_label);
    if support.has_dynamic_descriptor() {
        abi::emit_jump(emitter, &dynamic_label);
    } else {
        abi::emit_push_reg(emitter, "x1");
        emit_eval_invokable_object_descriptor_lookup(
            emitter,
            support,
            label_prefix,
            miss_label,
            "x0",
        );
    }
    if support.has_dynamic_descriptor() {
        emitter.label(&dynamic_label);
        emit_aarch64_eval_dynamic_callable_descriptor(
            module,
            emitter,
            support,
            fail_label,
            "x0",
            context_offset,
            source_offset,
        );
        abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    }
    emitter.label(&format!("{}_callable_cast_done", label_prefix));
}

/// Converts the x86_64 boxed eval argument slot into a callable descriptor pointer.
pub(super) fn emit_x86_64_cast_eval_callable_arg(
    module: &Module,
    emitter: &mut Emitter,
    data: &mut DataSection,
    support: &EvalCallableDescriptorSupport,
    label_prefix: &str,
    fail_label: &str,
    context_frame_offset: usize,
    source_offset: usize,
) {
    let string_label = format!("{}_callable_string", label_prefix);
    let array_label = format!("{}_callable_array", label_prefix);
    let object_label = format!("{}_callable_object", label_prefix);
    let descriptor_label = format!("{}_callable_descriptor", label_prefix);
    let dynamic_label = format!("{}_callable_dynamic", label_prefix);
    let miss_label = if support.has_dynamic_descriptor() {
        dynamic_label.as_str()
    } else {
        fail_label
    };
    emitter.instruction(&format!("mov rax, QWORD PTR [rbp - {}]", source_offset)); // reload the boxed eval value for callable validation
    emitter.instruction("call __rt_mixed_unbox");                               // expose the eval callable tag and payload words
    emitter.instruction("cmp rax, 1");                                          // runtime tag 1 means a string callable name
    emitter.instruction(&format!("je {}", string_label));                       // resolve string callables through descriptor metadata
    emitter.instruction("cmp rax, 4");                                          // runtime tag 4 means an indexed callable array
    emitter.instruction(&format!("je {}", array_label));                        // resolve static callable arrays through descriptor metadata
    emitter.instruction("cmp rax, 5");                                          // runtime tag 5 means an associative callable array
    emitter.instruction(&format!("je {}", array_label));                        // resolve static callable arrays with numeric keys
    emitter.instruction("cmp rax, 6");                                          // runtime tag 6 means an invokable object candidate
    emitter.instruction(&format!("je {}", object_label));                       // resolve invokable objects through descriptor metadata
    emitter.instruction("cmp rax, 10");                                         // runtime tag 10 is an AOT first-class callable descriptor
    emitter.instruction(&format!("je {}", descriptor_label));                   // preserve the already-valid callable ABI payload
    abi::emit_jump(emitter, miss_label);
    emitter.label(&descriptor_label);
    emitter.instruction("mov rax, rdi");                                        // return the unboxed callable descriptor pointer
    emitter.instruction("call __rt_incref");                                    // every cast path hands back an owned descriptor; the box keeps its own
    abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    emitter.label(&string_label);
    abi::emit_push_reg_pair(emitter, "rdi", "rdx");
    emit_eval_string_callable_descriptor_lookup(
        module,
        emitter,
        data,
        support,
        label_prefix,
        miss_label,
        "rax",
    );
    abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    emitter.label(&array_label);
    emit_x86_64_eval_callable_array_selector_slots(module, emitter, source_offset);
    emit_eval_callable_array_descriptor_lookup(
        emitter,
        data,
        support,
        label_prefix,
        miss_label,
        "rax",
    );
    abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    emitter.label(&object_label);
    if support.has_dynamic_descriptor() {
        abi::emit_jump(emitter, &dynamic_label);
    } else {
        abi::emit_push_reg(emitter, "rdi");
        emit_eval_invokable_object_descriptor_lookup(
            emitter,
            support,
            label_prefix,
            miss_label,
            "rax",
        );
    }
    if support.has_dynamic_descriptor() {
        emitter.label(&dynamic_label);
        emit_x86_64_eval_dynamic_callable_descriptor(
            module,
            emitter,
            support,
            fail_label,
            "rax",
            context_frame_offset,
            source_offset,
        );
        abi::emit_jump(emitter, &format!("{}_callable_cast_done", label_prefix));
    }
    emitter.label(&format!("{}_callable_cast_done", label_prefix));
}

/// Materializes a runtime descriptor that dispatches a callable through magician on ARM64.
fn emit_aarch64_eval_dynamic_callable_descriptor(
    module: &Module,
    emitter: &mut Emitter,
    support: &EvalCallableDescriptorSupport,
    fail_label: &str,
    result_reg: &str,
    context_offset: i64,
    source_offset: i64,
) {
    let descriptor_label = support
        .dynamic_descriptor_label
        .as_deref()
        .expect("dynamic eval callable descriptor must exist");
    let is_callable_symbol = module.target.extern_symbol("__elephc_eval_is_callable");
    emitter.instruction(&format!("ldr x0, [x29, #{}]", context_offset));        // load the active eval context for dynamic callable validation
    emitter.instruction(&format!("cbz x0, {}", fail_label));                    // reject dynamic eval callables when no context is active
    emitter.instruction(&format!("ldr x1, [x29, #{}]", source_offset));         // pass the original boxed eval callback value
    abi::emit_call_label(emitter, &is_callable_symbol);
    emitter.instruction("cmp w0, #0");                                          // check whether magician accepts the callback value
    emitter.instruction(&format!("b.eq {}", fail_label));                       // reject non-callable eval values
    emitter.instruction(&format!("ldr x0, [x29, #{}]", source_offset));         // reload the boxed callback value to retain it
    emitter.instruction("bl __rt_incref");                                      // retain the callback for descriptor capture ownership
    abi::emit_push_reg(emitter, "x0");
    abi::emit_load_int_immediate(
        emitter,
        "x0",
        (callable_descriptor::CALLABLE_DESC_RUNTIME_CAPTURE_OFFSET
            + EVAL_DYNAMIC_CALLABLE_CAPTURE_BYTES) as i64,
    );
    emitter.instruction("bl __rt_heap_alloc");                                  // allocate runtime descriptor storage with eval captures
    callable_descriptor::emit_copy_static_descriptor_to_runtime(emitter, "x0", descriptor_label);
    emitter.instruction(&format!("ldr x10, [x29, #{}]", context_offset));                                                                         // reload the active eval context for descriptor capture 0
    abi::emit_store_to_address(
        emitter,
        "x10",
        "x0",
        dynamic_capture_offset(EVAL_DYNAMIC_CONTEXT_CAPTURE),
    );
    abi::emit_load_temporary_stack_slot(emitter, "x10", 0);
    abi::emit_store_to_address(
        emitter,
        "x10",
        "x0",
        dynamic_capture_offset(EVAL_DYNAMIC_CALLBACK_CAPTURE),
    );
    abi::emit_release_temporary_stack(emitter, 16);
    if result_reg != "x0" {
        emitter.instruction(&format!("mov {}, x0", result_reg));                // return the dynamic eval callable descriptor
    }
}

/// Materializes a runtime descriptor that dispatches a callable through magician on x86_64.
fn emit_x86_64_eval_dynamic_callable_descriptor(
    module: &Module,
    emitter: &mut Emitter,
    support: &EvalCallableDescriptorSupport,
    fail_label: &str,
    result_reg: &str,
    context_frame_offset: usize,
    source_offset: usize,
) {
    let descriptor_label = support
        .dynamic_descriptor_label
        .as_deref()
        .expect("dynamic eval callable descriptor must exist");
    let is_callable_symbol = module.target.extern_symbol("__elephc_eval_is_callable");
    emitter.instruction(&format!(                                               // load the active eval context for dynamic callable validation
        "mov rdi, QWORD PTR [rbp - {}]",
        context_frame_offset
    ));
    emitter.instruction("test rdi, rdi");                                       // check whether a context was passed by magician
    emitter.instruction(&format!("jz {}", fail_label));                         // reject dynamic eval callables when no context is active
    emitter.instruction(&format!("mov rsi, QWORD PTR [rbp - {}]", source_offset)); // pass the original boxed eval callback value
    abi::emit_call_label(emitter, &is_callable_symbol);
    emitter.instruction("test eax, eax");                                       // check whether magician accepts the callback value
    emitter.instruction(&format!("jz {}", fail_label));                         // reject non-callable eval values
    emitter.instruction(&format!("mov rax, QWORD PTR [rbp - {}]", source_offset)); // reload the boxed callback value to retain it
    emitter.instruction("call __rt_incref");                                    // retain the callback for descriptor capture ownership
    abi::emit_push_reg(emitter, "rax");
    abi::emit_load_int_immediate(
        emitter,
        "rax",
        (callable_descriptor::CALLABLE_DESC_RUNTIME_CAPTURE_OFFSET
            + EVAL_DYNAMIC_CALLABLE_CAPTURE_BYTES) as i64,
    );
    emitter.instruction("call __rt_heap_alloc");                                // allocate runtime descriptor storage with eval captures
    callable_descriptor::emit_copy_static_descriptor_to_runtime(emitter, "rax", descriptor_label);
    emitter.instruction(&format!(                                               // reload the active eval context for descriptor capture 0
        "mov r10, QWORD PTR [rbp - {}]",
        context_frame_offset
    ));
    abi::emit_store_to_address(
        emitter,
        "r10",
        "rax",
        dynamic_capture_offset(EVAL_DYNAMIC_CONTEXT_CAPTURE),
    );
    abi::emit_load_temporary_stack_slot(emitter, "r10", 0);
    abi::emit_store_to_address(
        emitter,
        "r10",
        "rax",
        dynamic_capture_offset(EVAL_DYNAMIC_CALLBACK_CAPTURE),
    );
    abi::emit_release_temporary_stack(emitter, 16);
    if result_reg != "rax" {
        emitter.instruction(&format!("mov {}, rax", result_reg));               // return the dynamic eval callable descriptor
    }
}

/// Looks up a descriptor by the string callable currently saved on the temp stack.
fn emit_eval_string_callable_descriptor_lookup(
    _module: &Module,
    emitter: &mut Emitter,
    _data: &mut DataSection,
    support: &EvalCallableDescriptorSupport,
    _label_prefix: &str,
    fail_label: &str,
    _result_reg: &str,
) {
    if let Some(lookup_label) = support.string_lookup_label.as_deref() {
        let arg_reg = abi::int_arg_reg_name(emitter.target, 0);
        abi::emit_temporary_stack_address(emitter, arg_reg, 0);
        abi::emit_call_label(emitter, lookup_label);
        abi::emit_release_temporary_stack(emitter, 16);
        abi::emit_branch_if_int_result_zero(emitter, fail_label);
    } else {
        abi::emit_release_temporary_stack(emitter, 16);
        abi::emit_jump(emitter, fail_label);
    }
}

/// Bytes of the two owned element boxes kept beneath the callable-array selector slots.
///
/// `__elephc_eval_value_array_get` hands back an OWNED box (a string element is a fresh copy),
/// and `__elephc_eval_value_int` an owned index box. Both used to be dropped on the floor: every
/// `[$obj, 'method']` reaching a compiled `callable` parameter from eval leaked the two index
/// boxes, both element boxes and the method-name copy, and pinned the receiver. The index box is
/// released at once; the element boxes stay below the selector (whose string payload borrows
/// the copy) until the lookup has run, then `emit_eval_callable_array_descriptor_lookup`
/// releases them.
const EVAL_CALLABLE_ARRAY_ELEMENT_OWNER_BYTES: usize = 32;

/// Saves the receiver and method slots from an ARM64 boxed eval callable array.
fn emit_aarch64_eval_callable_array_selector_slots(
    module: &Module,
    emitter: &mut Emitter,
    source_offset: i64,
) {
    emit_aarch64_eval_callable_array_slot(module, emitter, 0, source_offset);
    abi::emit_push_reg(emitter, "x0");
    emit_aarch64_eval_callable_array_slot(module, emitter, 1, source_offset);
    abi::emit_push_reg(emitter, "x0");
    emitter.instruction("ldr x0, [sp, #16]");                                   // reload the owned receiver element box
    emitter.instruction("bl __rt_mixed_unbox");                                 // expose the receiver slot tag and payload
    emit_aarch64_push_mixed_unbox_payload(emitter);
    emitter.instruction("ldr x0, [sp, #32]");                                   // reload the owned method-name element box
    emitter.instruction("bl __rt_mixed_unbox");                                 // expose the method slot tag and payload
    emit_aarch64_push_mixed_unbox_payload(emitter);
}

/// Saves the receiver and method slots from an x86_64 boxed eval callable array.
fn emit_x86_64_eval_callable_array_selector_slots(
    module: &Module,
    emitter: &mut Emitter,
    source_offset: usize,
) {
    emit_x86_64_eval_callable_array_slot(module, emitter, 0, source_offset);
    abi::emit_push_reg(emitter, "rax");
    emit_x86_64_eval_callable_array_slot(module, emitter, 1, source_offset);
    abi::emit_push_reg(emitter, "rax");
    emitter.instruction("mov rax, QWORD PTR [rsp + 16]");                       // reload the owned receiver element box
    emitter.instruction("call __rt_mixed_unbox");                               // expose the receiver slot tag and payload
    emit_x86_64_push_mixed_unbox_payload(emitter);
    emitter.instruction("mov rax, QWORD PTR [rsp + 32]");                       // reload the owned method-name element box
    emitter.instruction("call __rt_mixed_unbox");                               // expose the method slot tag and payload
    emit_x86_64_push_mixed_unbox_payload(emitter);
}

/// Loads one ARM64 callable-array element as an owned box, releasing the index box.
///
/// `source_offset` is the boxed array's frame slot: the parameter bridges and the property
/// setter keep it at different `x29` offsets, and a fixed `-16` read the wrong slot in the setter.
fn emit_aarch64_eval_callable_array_slot(
    module: &Module,
    emitter: &mut Emitter,
    index: usize,
    source_offset: i64,
) {
    let value_int_symbol = module.target.extern_symbol("__elephc_eval_value_int");
    let array_get_symbol = module.target.extern_symbol("__elephc_eval_value_array_get");
    abi::emit_load_int_immediate(emitter, "x0", index as i64);
    abi::emit_call_label(emitter, &value_int_symbol);
    emitter.instruction("str x0, [sp, #-16]!");                                 // preserve the owned boxed callable-array index
    emitter.instruction("ldr x1, [sp]");                                        // pass the boxed selector index to eval's array reader
    emitter.instruction(&format!("ldr x0, [x29, #{}]", source_offset));         // pass the boxed callable array to eval's array reader
    abi::emit_call_label(emitter, &array_get_symbol);
    emitter.instruction("str x0, [sp, #8]");                                    // park the owned element box beside the index box
    emitter.instruction("ldr x0, [sp]");                                        // reload the owned index box
    emitter.instruction("bl __rt_decref_any");                                  // release the index box the reader no longer needs
    emitter.instruction("ldr x0, [sp, #8]");                                    // return the owned element box
    emitter.instruction("add sp, sp, #16");                                     // discard the index scratch slot
}

/// Loads one x86_64 callable-array element as an owned box, releasing the index box.
fn emit_x86_64_eval_callable_array_slot(
    module: &Module,
    emitter: &mut Emitter,
    index: usize,
    source_offset: usize,
) {
    let value_int_symbol = module.target.extern_symbol("__elephc_eval_value_int");
    let array_get_symbol = module.target.extern_symbol("__elephc_eval_value_array_get");
    abi::emit_load_int_immediate(emitter, "rdi", index as i64);
    abi::emit_call_label(emitter, &value_int_symbol);
    abi::emit_push_reg(emitter, "rax");
    emitter.instruction("mov rsi, QWORD PTR [rsp]");                            // pass the boxed selector index to eval's array reader
    emitter.instruction(&format!("mov rdi, QWORD PTR [rbp - {}]", source_offset)); // pass the boxed callable array to eval's array reader
    abi::emit_call_label(emitter, &array_get_symbol);
    emitter.instruction("mov QWORD PTR [rsp + 8], rax");                        // park the owned element box beside the index box
    emitter.instruction("mov rax, QWORD PTR [rsp]");                            // reload the owned index box
    emitter.instruction("call __rt_decref_any");                                // release the index box the reader no longer needs
    emitter.instruction("mov rax, QWORD PTR [rsp + 8]");                        // return the owned element box
    emitter.instruction("add rsp, 16");                                         // discard the index scratch slot
}

/// Preserves the current ARM64 mixed-unbox tag and payload on the temp stack.
fn emit_aarch64_push_mixed_unbox_payload(emitter: &mut Emitter) {
    abi::emit_push_reg_pair(emitter, "x1", "x2");
    abi::emit_push_reg(emitter, "x0");
}

/// Preserves the current x86_64 mixed-unbox tag and payload on the temp stack.
fn emit_x86_64_push_mixed_unbox_payload(emitter: &mut Emitter) {
    abi::emit_push_reg_pair(emitter, "rdi", "rdx");
    abi::emit_push_reg(emitter, "rax");
}

/// Looks up a descriptor from saved callable-array selector slots.
fn emit_eval_callable_array_descriptor_lookup(
    emitter: &mut Emitter,
    _data: &mut DataSection,
    support: &EvalCallableDescriptorSupport,
    _label_prefix: &str,
    fail_label: &str,
    _result_reg: &str,
) {
    if let Some(lookup_label) = support.array_lookup_label.as_deref() {
        let arg_reg = abi::int_arg_reg_name(emitter.target, 0);
        abi::emit_temporary_stack_address(emitter, arg_reg, 0);
        abi::emit_call_label(emitter, lookup_label);
        abi::emit_release_temporary_stack(emitter, MIXED_SELECTOR_BYTES);
        emit_release_callable_array_element_owners(emitter, true);
        abi::emit_branch_if_int_result_zero(emitter, fail_label);
    } else {
        abi::emit_release_temporary_stack(emitter, MIXED_SELECTOR_BYTES);
        emit_release_callable_array_element_owners(emitter, false);
        abi::emit_jump(emitter, fail_label);
    }
}

/// Releases the two owned element boxes kept beneath the selector slots, then pops them.
fn emit_release_callable_array_element_owners(emitter: &mut Emitter, preserve_result: bool) {
    let result = abi::int_result_reg(emitter);
    let base = if preserve_result {
        abi::emit_push_reg(emitter, result);
        16
    } else {
        0
    };
    for slot in 0..2 {
        abi::emit_load_temporary_stack_slot(emitter, result, base + slot * 16);
        abi::emit_call_label(emitter, "__rt_decref_any");
    }
    if preserve_result {
        abi::emit_pop_reg(emitter, result);
    }
    abi::emit_release_temporary_stack(emitter, EVAL_CALLABLE_ARRAY_ELEMENT_OWNER_BYTES);
}

/// Looks up a descriptor from a saved invokable-object receiver.
fn emit_eval_invokable_object_descriptor_lookup(
    emitter: &mut Emitter,
    support: &EvalCallableDescriptorSupport,
    _label_prefix: &str,
    fail_label: &str,
    _result_reg: &str,
) {
    if let Some(lookup_label) = support.object_lookup_label.as_deref() {
        let arg_reg = abi::int_arg_reg_name(emitter.target, 0);
        abi::emit_temporary_stack_address(emitter, arg_reg, 0);
        abi::emit_call_label(emitter, lookup_label);
        abi::emit_release_temporary_stack(emitter, SAVED_OBJECT_RECEIVER_BYTES);
        abi::emit_branch_if_int_result_zero(emitter, fail_label);
    } else {
        abi::emit_release_temporary_stack(emitter, SAVED_OBJECT_RECEIVER_BYTES);
        abi::emit_jump(emitter, fail_label);
    }
}

/// Branches unless saved selector slots match one instance callable-array case.
fn emit_branch_if_instance_callable_array_case_mismatch(
    emitter: &mut Emitter,
    data: &mut DataSection,
    case: &EvalInstanceMethodCallableCase,
    next_label: &str,
) {
    emit_branch_if_stack_tag_mismatch(
        emitter,
        MIXED_RECEIVER_TAG_OFFSET,
        MIXED_TAG_OBJECT,
        next_label,
    );
    emit_branch_if_stack_tag_mismatch(
        emitter,
        MIXED_METHOD_TAG_OFFSET,
        MIXED_TAG_STRING,
        next_label,
    );
    emit_branch_if_receiver_class_id_mismatch(
        emitter,
        case.class_id,
        MIXED_RECEIVER_PAYLOAD_OFFSET,
        next_label,
    );
    emit_branch_if_stack_string_mismatch(
        emitter,
        data,
        MIXED_METHOD_PAYLOAD_OFFSET,
        MIXED_METHOD_PAYLOAD_OFFSET + 8,
        case.method_name.as_bytes(),
        next_label,
    );
}

/// Branches unless saved selector slots match one static callable-array case.
fn emit_branch_if_static_callable_array_case_mismatch(
    emitter: &mut Emitter,
    data: &mut DataSection,
    case: &RuntimeStaticMethodCallableCase,
    next_label: &str,
) {
    emit_branch_if_stack_tag_mismatch(
        emitter,
        MIXED_RECEIVER_TAG_OFFSET,
        MIXED_TAG_STRING,
        next_label,
    );
    emit_branch_if_stack_tag_mismatch(
        emitter,
        MIXED_METHOD_TAG_OFFSET,
        MIXED_TAG_STRING,
        next_label,
    );
    emit_branch_if_static_class_string_mismatch(
        emitter,
        data,
        MIXED_RECEIVER_PAYLOAD_OFFSET,
        MIXED_RECEIVER_PAYLOAD_OFFSET + 8,
        &case.class_name,
        next_label,
    );
    emit_branch_if_stack_string_mismatch(
        emitter,
        data,
        MIXED_METHOD_PAYLOAD_OFFSET,
        MIXED_METHOD_PAYLOAD_OFFSET + 8,
        case.method_name.as_bytes(),
        next_label,
    );
}

/// Branches when the saved receiver object's class id does not match `class_id`.
fn emit_branch_if_receiver_class_id_mismatch(
    emitter: &mut Emitter,
    class_id: u64,
    receiver_offset: usize,
    next_label: &str,
) {
    match emitter.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            abi::emit_load_temporary_stack_slot(emitter, "x9", receiver_offset);
            emitter.instruction(&format!("cbz x9, {}", next_label));            // reject null receiver pointers before reading their class id
            emitter.instruction("ldr x10, [x9]");                               // load the receiver runtime class id from the object header
            abi::emit_load_int_immediate(emitter, "x11", class_id as i64);
            emitter.instruction("cmp x10, x11");                                // compare receiver class id against this callable case
            emitter.instruction(&format!("b.ne {}", next_label));               // try the next callable target when the receiver class differs
        }
        crate::codegen::platform::Arch::X86_64 => {
            abi::emit_load_temporary_stack_slot(emitter, "r10", receiver_offset);
            emitter.instruction("test r10, r10");                               // reject null receiver pointers before reading their class id
            emitter.instruction(&format!("je {}", next_label));                 // try the next callable target when the receiver pointer is null
            emitter.instruction("mov r11, QWORD PTR [r10]");                    // load the receiver runtime class id from the object header
            abi::emit_load_int_immediate(emitter, "r10", class_id as i64);
            emitter.instruction("cmp r11, r10");                                // compare receiver class id against this callable case
            emitter.instruction(&format!("jne {}", next_label));                // try the next callable target when the receiver class differs
        }
    }
}

/// Allocates a runtime descriptor and captures the saved receiver object.
fn emit_runtime_descriptor_with_saved_receiver_capture(
    emitter: &mut Emitter,
    descriptor_label: &str,
    receiver_offset: usize,
    result_reg: &str,
) {
    let total_bytes = callable_descriptor::CALLABLE_DESC_RUNTIME_CAPTURE_OFFSET + 16;
    match emitter.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            abi::emit_load_temporary_stack_slot(emitter, "x0", receiver_offset);
            emitter.instruction("bl __rt_incref");                              // retain the receiver for the runtime callable descriptor
            abi::emit_push_reg(emitter, "x0");
            abi::emit_load_int_immediate(emitter, "x0", total_bytes as i64);
            emitter.instruction("bl __rt_heap_alloc");                          // allocate receiver-bound callable descriptor storage
            callable_descriptor::emit_copy_static_descriptor_to_runtime(
                emitter,
                "x0",
                descriptor_label,
            );
            abi::emit_push_reg(emitter, "x0");
            abi::emit_load_temporary_stack_slot(emitter, "x11", 0);
            abi::emit_load_temporary_stack_slot(emitter, "x0", 16);
            callable_descriptor::emit_store_current_result_to_runtime_capture(
                emitter,
                "x11",
                0,
                &PhpType::Object(String::new()),
            );
            abi::emit_pop_reg(emitter, result_reg);
            abi::emit_release_temporary_stack(emitter, 16);
        }
        crate::codegen::platform::Arch::X86_64 => {
            abi::emit_load_temporary_stack_slot(emitter, "rax", receiver_offset);
            emitter.instruction("call __rt_incref");                            // retain the receiver for the runtime callable descriptor
            abi::emit_push_reg(emitter, "rax");
            abi::emit_load_int_immediate(emitter, "rax", total_bytes as i64);
            emitter.instruction("call __rt_heap_alloc");                        // allocate receiver-bound callable descriptor storage
            callable_descriptor::emit_copy_static_descriptor_to_runtime(
                emitter,
                "rax",
                descriptor_label,
            );
            abi::emit_push_reg(emitter, "rax");
            abi::emit_load_temporary_stack_slot(emitter, "rcx", 0);
            abi::emit_load_temporary_stack_slot(emitter, "rax", 16);
            callable_descriptor::emit_store_current_result_to_runtime_capture(
                emitter,
                "rcx",
                0,
                &PhpType::Object(String::new()),
            );
            abi::emit_pop_reg(emitter, result_reg);
            abi::emit_release_temporary_stack(emitter, 16);
        }
    }
}

/// Branches when a saved Mixed tag stack slot does not equal `expected_tag`.
fn emit_branch_if_stack_tag_mismatch(
    emitter: &mut Emitter,
    tag_offset: usize,
    expected_tag: i64,
    next_label: &str,
) {
    match emitter.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            abi::emit_load_temporary_stack_slot(emitter, "x9", tag_offset);
            emitter.instruction(&format!("cmp x9, #{}", expected_tag));         // compare the callable-array selector runtime tag
            emitter.instruction(&format!("b.ne {}", next_label));               // try the next callable-array target when the tag differs
        }
        crate::codegen::platform::Arch::X86_64 => {
            abi::emit_load_temporary_stack_slot(emitter, "r10", tag_offset);
            emitter.instruction(&format!("cmp r10, {}", expected_tag));         // compare the callable-array selector runtime tag
            emitter.instruction(&format!("jne {}", next_label));                // try the next callable-array target when the tag differs
        }
    }
}

/// Branches when a saved stack string does not match the expected PHP name.
fn emit_branch_if_stack_string_mismatch(
    emitter: &mut Emitter,
    data: &mut DataSection,
    ptr_offset: usize,
    len_offset: usize,
    expected: &[u8],
    next_label: &str,
) {
    let matched_label = format!("{}_matched", next_label);
    emit_stack_string_compare_branch(
        emitter,
        data,
        ptr_offset,
        len_offset,
        expected,
        &matched_label,
    );
    abi::emit_jump(emitter, next_label);
    emitter.label(&matched_label);
}

/// Branches when a saved class string does not match bare or leading-slash forms.
fn emit_branch_if_static_class_string_mismatch(
    emitter: &mut Emitter,
    data: &mut DataSection,
    ptr_offset: usize,
    len_offset: usize,
    class_name: &str,
    next_label: &str,
) {
    let matched_label = format!("{}_class_matched", next_label);
    emit_stack_string_compare_branch(
        emitter,
        data,
        ptr_offset,
        len_offset,
        class_name.as_bytes(),
        &matched_label,
    );
    let leading_slash = format!("\\{}", class_name);
    emit_stack_string_compare_branch(
        emitter,
        data,
        ptr_offset,
        len_offset,
        leading_slash.as_bytes(),
        &matched_label,
    );
    abi::emit_jump(emitter, next_label);
    emitter.label(&matched_label);
}

/// Compares a saved stack string with `expected` and branches on equality.
fn emit_stack_string_compare_branch(
    emitter: &mut Emitter,
    data: &mut DataSection,
    ptr_offset: usize,
    len_offset: usize,
    expected: &[u8],
    matched_label: &str,
) {
    let (expected_label, expected_len) = data.add_string(expected);
    match emitter.target.arch {
        crate::codegen::platform::Arch::AArch64 => {
            abi::emit_load_temporary_stack_slot(emitter, "x1", ptr_offset);
            abi::emit_load_temporary_stack_slot(emitter, "x2", len_offset);
            abi::emit_symbol_address(emitter, "x3", &expected_label);
            abi::emit_load_int_immediate(emitter, "x4", expected_len as i64);
            abi::emit_call_label(emitter, "__rt_strcasecmp");
            emitter.instruction("cmp x0, #0");                                  // check whether the runtime method string matched
            emitter.instruction(&format!("b.eq {}", matched_label));            // select this callable-array target when names match
        }
        crate::codegen::platform::Arch::X86_64 => {
            abi::emit_load_temporary_stack_slot(emitter, "rdi", ptr_offset);
            abi::emit_load_temporary_stack_slot(emitter, "rsi", len_offset);
            abi::emit_symbol_address(emitter, "rdx", &expected_label);
            abi::emit_load_int_immediate(emitter, "rcx", expected_len as i64);
            abi::emit_call_label(emitter, "__rt_strcasecmp");
            emitter.instruction("test rax, rax");                               // check whether the runtime method string matched
            emitter.instruction(&format!("je {}", matched_label));              // select this callable-array target when names match
        }
    }
}
